konsole_tabs:
/* Generated by ~/.config/plasma-rice/rice.py from the wallpaper palette. Do not edit. */
QTabBar { background: rgba(1,1,1, 217); }
QTabBar::tab {
    background: transparent; color: #696969;
    border: 1px solid transparent; border-radius: 10px;
    padding: 4px 12px; margin: 8px 2px 2px 2px;
    min-width: 7em; max-width: 22em;
}
QTabBar::tab:first { margin-left: 12px; }
QTabBar::tab:hover:!selected { background: rgba(222,222,222, 20); color: #a4a4a4; }
QTabBar::tab:selected {
    background: rgba(185,190,198, 41); color: #dedede;
    border-color: rgba(185,190,198, 82);
}

zen:
/* Rice for Zen: generated by ~/.config/plasma-rice/apps.py from the wallpaper palette. Do not edit. */
:root, :host(:is(.anonymous-content-host, notification-message)) {
  --zen-primary-color: #b9bec6 !important;
  --zen-branding-dark: #010101 !important;
  --zen-colors-primary: color-mix(in srgb, #b9bec6 22%, #020202) !important;
  --zen-colors-secondary: color-mix(in srgb, #b9bec6 32%, #020202) !important;
  --zen-colors-tertiary: #000000 !important;
  --zen-colors-hover-bg: color-mix(in srgb, #b9bec6 14%, #040404) !important;
  --zen-colors-primary-foreground: #dedede !important;
  --zen-colors-border: rgba(36,36,36, 0.55) !important;
  --zen-colors-border-contrast: rgba(36,36,36, 0.3) !important;
  --zen-colors-input-bg: #040404 !important;
  --zen-input-border-color: #242424 !important;
  --zen-dialog-background: #020202 !important;
  --zen-urlbar-background: #040404 !important;
  --zen-main-browser-background: linear-gradient(135deg, rgba(44,46,49, 0.72) 0%, rgba(0,0,0, 0.84) 52%, rgba(44,46,49, 0.68) 100%) !important;
  --zen-main-browser-background-toolbar: linear-gradient(135deg, rgba(44,46,49, 0.72) 0%, rgba(0,0,0, 0.84) 52%, rgba(44,46,49, 0.68) 100%) !important;
  --toolbox-textcolor: #dedede !important;
  --toolbar-field-color: #dedede !important;
  --arrowpanel-background: #040404 !important;
  --arrowpanel-color: #dedede !important;
  --arrowpanel-border-color: rgba(36,36,36, 0.6) !important;
  --panel-separator-color: rgba(36,36,36, 0.6) !important;
  --focus-outline-color: #b9bec6 !important;
  --zen-sidebar-themed-icon-fill: #a4a4a4 !important;
}

/* Zen paints the workspace gradient on these layers and sets its variables inline on them,
   so override the layers themselves (::before is the cross-fade target while switching spaces) */
.zen-browser-generic-background::after,
.zen-browser-generic-background::before {
  background: linear-gradient(135deg, rgba(44,46,49, 0.72) 0%, rgba(0,0,0, 0.84) 52%, rgba(44,46,49, 0.68) 100%) !important;
}

/* selected tab: a soft accent wash with a hairline, instead of plain white */
.tabbrowser-tab:is([selected], [multiselected]) .tab-background {
  background-color: rgba(185,190,198, 0.16) !important;
  box-shadow: inset 0 0 0 1px rgba(185,190,198, 0.32) !important;
}
.tabbrowser-tab:not([selected]):hover .tab-background {
  background-color: rgba(222,222,222, 0.07) !important;
}

/* command bar / url bar popup */
#urlbar[breakout-extend] > .urlbar-background,
#urlbar[breakout-extend] #urlbar-background {
  background-color: #040404 !important;
  border: 1px solid rgba(36,36,36, 0.7) !important;
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.45) !important;
}
.urlbarView-row[selected] {
  background-color: rgba(185,190,198, 0.18) !important;
}

/* menus and popups */
menupopup, panel {
  --panel-background: #040404 !important;
  --panel-color: #dedede !important;
  --panel-border-color: rgba(36,36,36, 0.6) !important;
}
/* Rice for Zen: generated by ~/.config/plasma-rice/apps.py. Do not edit. */
:root {
  scrollbar-color: rgba(72,72,72, 0.7) transparent;
}
@-moz-document url("about:blank"), url("about:newtab"), url("about:home"), url("about:privatebrowsing") {
  html, body { background-color: #010101 !important; }
}
